window.DOSIK=window.DOSIK||{};DOSIK["yc_career"]={"1":[{"t":"tree","title":"진로상담의 목표","root":"진로상담의 목표","branches":[["의사결정","내담자의 의사결정기술을 향상시킨다 · 합리적인 의사결정능력을 향상시킨다"],["대인관계","내담자의 대인관계기술을 향상시킨다"],["진로탐색·설계","내담자의 진로탐색활동을 구체적으로 돕는다 · 내담자가 진로설계를 스스로 할 수 있도록 돕는다"]]},{"t":"table","title":"상담자의 역할","head":["항목","내용"],"rows":[["검사","진로 관련 검사를 실시하고 해석한다"],["학교급별 활동","초등학생에게는 진로인식을 위한 활동을 하도록 한다 · 중학생에게는 진로탐색을 위한 활동을 하도록 한다"],["윤리","상담윤리를 지키며 진행한다"],["내담자 이해","내담자의 문제를 내담자의 입장에서 이해한다 · 내담자마다 성격, 적성, 흥미 등이 다름을 고려한다 · 내담자의 잠재력을 발견하고 발현될 수 있도록 돕는다"]]}],"2":[{"t":"flow","title":"특성요인 진로상담","steps":["내담자의 독특성 또는 개별성을 탐색하기 위하여 사례연구나 검사결과를 통해 자료를 수집하고 요약한다","조정가능성 및 문제의 가능한 결과를 판단하고, 이를 통해 내담자가 고려해야 할 대안적 조치들과 조정사항들을 찾는다"]}],"3":[{"t":"tree","title":"로우의 욕구이론","root":"로우의 욕구이론","branches":[["직업군","직업을 흥미에 기초하여 8개 직업군으로 제안하였다"],["이론의 바탕","매슬로우(A. Maslow) 이론의 영향을 받았다 · 성격과 직업분류를 통합하였다"],["부모-자녀 관계","아동기의 경험 중 부모-자녀 관계는 직업선택에 중요한 영향을 미치는 요인으로 간주하였다 · 부모와 자녀 간의 상호작용은 정서집중형, 회피형, 수용형으로 구분하였다"]]}],"4":[{"t":"table","title":"홀랜드의 직업성격유형이론","head":["개념","내용"],"rows":[["일관성","성격유형과 환경모형 간의 관련 정도"],["변별성","유형간의 상대적 중요도의 관계"],["정체성","환경적 정체성은 환경이나 조직이 분명하고 통합된 목표, 일, 보상이 일관되게 주어질 때 생긴다"],["계측성","육각형 내에서 유형들 간의 거리는 그들의 이론적 관계에 반비례한다"]]}],"5":[{"t":"flow","title":"긴즈버그의 진로발달 단계","steps":["흥미단계: 자신의 흥미에 입각해서 직업을 선택하려는 경향","능력단계: 직업에 따라 보수와 필요로 하는 교육이 다르다는 것을 알게 된다","가치단계: 직업선택을 할 때 관련된 모든 요인들을 인정하고 자신의 가치관 및 생애 목표에 비추어 평가해 본다","전환단계: 주관적인 요소에서 현실적인 외적 요소로 관심을 돌리기 시작한다"]}],"6":[{"t":"tree","title":"수퍼의 생애진로발달이론","root":"수퍼의 이론","branches":[["전 생애적 발달","진로발달을 전 생애적인 발달과정으로 보았다"],["자기개념","아동기부터 일의 세계에 관한 여러 경험을 하게 되면서 일과 관련된 자기개념을 형성한다고 하였다"],["진로적응력","성인기의 진로발달을 이해하기 위해서는 진로적응력의 개념이 중요하다고 보았다"],["역할과 시간","진로발달에 있어서 역할과 시간의 개념을 도입하였다"]]}],"7":[{"t":"flow","title":"갓프레드슨의 발달 단계","steps":["2단계 성유형 획득단계: 초등학교 저학년 시기로 성역할을 지향","3단계 사회적 가치를 획득하는 단계: 아동기에서 청소년기에로 이행하는 시기로, 사회적 가치, 능력, 명성을 지향","4단계 내적 자아를 확립하는 단계: 청소년기로, 자신만의 흥미, 적성, 가치관, 성격 등을 이해할 수 있다"]},{"t":"def","term":"제한-타협","text":"사람들은 자아개념에 부합하는 직업들을 포기할 때 흥미, 명성, 성유형의 순서대로 포기한다"}],"8":[{"t":"vs","title":"타이드만과 오하라의 진로의사결정 단계","cols":[{"name":"예상기","items":["탐색 단계: 자신이 정한 목적을 전반적으로 고려하고, 대안을 추진해 나갈 수 있는 능력과 여건을 평가하며, 대안에 대한 가치를 분석한다","구체화 단계: 가능한 대안을 선택하며, 각 대안의 장단점을 검토하여 서열화 및 조직화 한다","선택기는 구체화 과정을 통해 나타난 결과를 토대로 명확한 목표를 설정하는 단계"]},{"name":"실천기","items":["개인의 진로의사결정 단계를 직업정체감 형성 과정에 따라 예상기와 실천기로 나누어 설명한다"]}]},{"t":"def","term":"직업정체감","text":"개인이 일에 직면했을 때 분화와 통합을 통하여 직업정체감을 형성한다고 보았다"}],"9":[{"t":"tree","title":"크럼볼츠의 우연학습이론","root":"우연학습이론","branches":[["통제하기 어려운 요인","진로결정과정에서 개인이 통제하기 어려운 요인들이 영향을 미치고 있음을 강조한다 · 진로개발과정에서 우연(happenstance)이 중요한 영향을 준다"],["상담 방향","내담자가 호소하는 문제도 중요하지만 예기치 않은 사건이나 문제발생을 대비하는 역량을 키워주는 것이 중요하다 · 상담의 성공여부는 내담자가 상담실 밖에서 다양한 경험을 위해 얼마나 노력하고 성장하는가에 좌우된다"],["촉진할 기술","내담자의 호기심(curiosity), 인내심(persistence), 유연성(flexibility), 낙관성(optimism), 위험감수(risk-taking) 등의 기술을 촉진시킨다"]]},{"t":"tree","title":"사회학습이론","root":"사회학습이론","branches":[["과제접근 기술","개인은 어떤 과제를 성취하기 위하여 과제접근 기술을 사용한다"],["학습경험","학습경험은 도구적 학습과 연합적 학습을 통하여 이루어진다"],["환경과의 상호작용","환경과의 상호작용을 통해 무엇을 학습했는가를 중요시한다"]]}],"10":[{"t":"cause","title":"사회인지진로이론의 흐름","causes":["자기효능감","결과기대"],"result":"흥미","effects":["흥미는 다시 진로대안 선택의 목표에 영향을 준다"]},{"t":"table","title":"사회인지진로이론의 개념과 개입","head":["항목","내용"],"rows":[["결과기대","적응적 진로행동에 대하여 예상되는 결과에 관한 기대와 개인적 신념으로 가치와 관련된다"],["환경맥락적 요인","근접맥락과 배경맥락으로 세분화된다"],["목표","특정한 결과에 도움이 되는 행동에 전념하려는 의도나 계획이며, 행동을 자기조절하는데 있어서 중요하다"],["진로장벽·직업정보","내담자가 선택 가능한 진로를 일찍 제외하도록 만든 진로장벽을 확인하고 평가하는 것이 중요하다 · 내담자의 잘못된 직업정보를 점검하고 수정하는 것이 중요하다"],["개입 전략","자기효능감 점검, 결과기대에 대한 탐색과 현실성 강화, 진로준비행동 촉진 등이 중요한 개입 전략이다 · 부적절한 자기효능감이나 결과에 대한 기대 때문에 내담자가 제외한 진로대안들을 다시 확인하는 것이 중요하다"]]}],"12":[{"t":"def","term":"인식단계","text":"개인이 심리적 불균형을 느끼고 어떤 결정을 해야 할 필요성을 인식한다"},{"t":"table","title":"하렌의 진로의사결정 유형","head":["유형","내용"],"rows":[["합리적 유형","정확한 정보를 수집하고, 논리적으로 의사결정을 해 나가며, 의사결정에 대한 책임을 진다"],["직관적 유형","의사결정의 기초로 상상을 사용하고, 현재의 감정에 주의를 기울이며, 정서적 감각을 사용한다"],["의존적 유형","의사결정에 대한 개인적인 책임을 부정하고 그 책임을 외부로 돌리는 경향이 있다"]]},{"t":"tree","title":"인지적 정보처리이론","root":"인지적 정보처리이론","branches":[["진로문제의 해결","고도의 기억력을 필요로 하는 과제"],["진로발달","지식 구조의 계속적인 성장과 변화를 내포한다"],["진로정체감","자기인식에 달려있다"],["진로성숙도","진로문제를 해결하는 개인의 능력과 관련된다"]]}],"13":[{"t":"flow","title":"사비카스의 진로상담 방식","steps":["내담자로 하여금 진로나 직업선택과 관련된 본인의 이야기(storytelling)를 하도록 한다","진로이야기를 끌어내기 위해 진로유형면접(career style interview)을 사용한다","진로유형면접 자료를 근거로 내담자의 생애주제(life themes)를 이끌어 낸다","'구성 - 해체 - 재구성 - 협력구성'의 내러티브 방식을 기본으로 한다"]},{"t":"table","title":"기존 이론에 대한 비판","head":["항목","내용"],"rows":[["맥락의 한계","기존의 이론들은 개인의 진로에 영향을 주는 객관적 맥락과 주관적 맥락의 영향을 모두 포함하지 못하고 있다"],["매칭·조화","기존의 이론들은 매칭 또는 조화의 역동에만 초점을 두고 인간의 적응적인 특성을 충분히 반영하지 못하고 있다"],["의미부여","기존의 이론들은 인간이 현상과 경험을 새롭게 해석하고 의미부여하고 있는 점을 간과하고 있다"],["우연","진로발달이 예상하지 못했던 사건과 경험, 즉 우연에 의해 변화될 수 있음을 충분히 고려하지 못하고 있다"]]},{"t":"def","term":"진로적응도","text":"진로적응도의 자원과 전략에 따라서 관심, 통제, 호기심, 자신감의 차원으로 제시하였다 · 개인이 환경의 영향을 받기도 하지만, 개인도 환경을 만들어가는 발달의 주체임을 강조한다"}],"14":[{"t":"tree","title":"슬로스버그의 전환 유형","root":"전환의 유형","branches":[["예측된 전환","슬로스버그(N. Schlossberg)가 나눈 유형"],["예측하지 못한 전환","슬로스버그가 나눈 유형"],["만성적인 전환","슬로스버그가 나눈 유형"],["일어나지 않은 전환","슬로스버그가 나눈 유형"]]},{"t":"table","title":"진로전환의 특성과 요인","head":["항목","내용"],"rows":[["양가적인 특성","직업생활 전환에는 청사진과 위협의 양가적인 특성이 있다 · 진로전환에는 양가적인 특성이 있다"],["기대치 전환","새로운 일자리로 진입하는 경우 기대치 전환이 중요하다고 보고 있다"],["4S","개인의 직업생활 전환에 영향을 주는 요소로 자아(Self), 지원(Support), 상황(Situation), 전략(Strategies) 등을 강조한다"],["적응 개입","새로운 일자리에 적응하기 위해서는 네트워킹, 가족지원정책, 경제적 안정 등 다양한 차원의 개입이 요구된다"],["증진요인","경제적 안정, 정서적 안정, 건강, 전환 기술, 지지적 직업환경, 전환에 대한 지지 등"],["진로전환검사(CTI)","준비도, 자기효능감(confidence), 지각된 지지, 내외적 통제, 자기중심-관계중심(independence-interdependence)으로 구성"]]}],"16":[{"t":"vs","title":"진로상담 기법","cols":[{"name":"가족 맥락을 보는 기법","items":["가족의 맥락 속에서 내담자 이해를 촉진시켜주는 기법","내담자의 진로에 미친 영향을 확인할 수 있다","내담자의 진로장벽을 확인할 수 있다","내담자의 진로정보를 여러 가지 방법으로 탐색할 수 있다"]},{"name":"구조화된 면접기법","items":["아들러(A. Adler)의 개인심리학에 기초하였다","내담자의 정보를 수집하는 단계에서 사용될 수 있다","상담자와 내담자의 긍정적인 라포 형성에 도움을 준다","진로사정, 일상적인 하루, 강점과 장애, 요약 등의 · 네 부분으로 구성되어 있다"]}]},{"t":"table","title":"가족 맥락 기법의 쓰임","head":["항목","내용"],"rows":[["사용 목적","사용목적을 내담자에게 설명해야 한다"],["가치 확인","내담자 가족의 지배적인 직업가치를 확인하기 위해 사용할 수 있다"],["진로정보 수집","진로정보 수집단계에서 사용될 수 있는 질적 평가과정"],["진로기대 형성","내담자의 진로기대형성에 중요한 역할을 한 가족이 누구인지 확인이 가능하다"]]}],"17":[{"t":"table","title":"진로심리검사","head":["검사","내용"],"rows":[["적성분류검사(Differential Aptitude Test: DAT)","일반적성검사와 특수적성검사가 있다"],["스트롱흥미검사(SII)","특정 직업에 종사하고 있는 사람들이 비슷한 흥미를 갖고 있다는 전제로 개발 · 좋아함-무관심-싫어함 정도를 파악하여 직업군에 대한 흥미 형태를 결정한다"],["미네소타 직업가치 검사(MIQ)","직업과 관련된 가치체계를 측정하기 위한 검사"],["진로성숙도검사(Career Maturity Inventory: CMI)","초등학교 6학년부터 고등학교 3학년을 대상으로 진로의사결정에 대한 태도와 능력을 측정하기 위해 개발 · 진로계획 태도와 능력을 측정한다"],["진로의사결정수준검사(Assessment of Career Decision Making: ACDM)","합리적, 직관적, 의존적 유형을 측정한다"]]},{"t":"table","title":"상담 질문과 관계 형성","head":["항목","내용"],"rows":[["촉진적 관계","내담자가 기대하는 것이 무엇인가와 같은 질문을 통해 촉진적 관계를 형성한다"],["내담자 관점 수용","내담자의 비합리적인 진로기대 및 진로신념 등을 살펴보면서 내담자의 관점을 수용한다"],["생활양식","내담자가 가장 중시하는 욕구가 무엇인가를 통해서 내담자의 생활양식을 확인한다"],["문제 구체화","내담자에게 특정한 일을 좋아하는 이유 등을 질문하면서 내담자의 문제를 구체화 한다"]]}],"18":[{"t":"table","title":"진로정보와 직업분류","head":["항목","내용"],"rows":[["한국표준직업분류","직업을 11개 직업군으로 분류 · 직능수준을 교육과 훈련정도에 따라 4단계로 구분"],["한국고용직업분류","직업을 대분류, 중분류, 소분류, 세분류로 구분"],["한국직업사전","부가직업정보로 직업별 필요한 정규교육수준, 숙련기간, 자격면허 등을 제공"]]},{"t":"table","title":"진로정보의 성격","head":["항목","내용"],"rows":[["의미","일과 관련한 교육적, 직업적, 심리사회적 정보"],["기능","직업에 대한 이해를 향상시킴으로써 합리적인 의사결정과정을 돕는다"],["범위","자원봉사, 직업체험, 인턴십 활동 등과 같이 직접적인 경험에 의해 수집한 자료도 포함 · 직업정보뿐만 아니라 내담자 이해와 관련한 다양한 정보를 포함"]]}],"19":[{"t":"tree","title":"집단진로상담","root":"집단진로상담","branches":[["형태","집단의 형태로 진로상담이 진행됨을 의미한다"],["직업정보 제공","공통적으로 필요로 하는 직업정보를 효율적으로 제공할 수 있는 기회가 된다"],["직업적 적합성","자신의 직업적 적합성을 객관적이고 현실적으로 이해할 수 있다"],["진로계획 검토","자신의 진로계획을 검토하게 하는 기회를 제공한다"],["집단원 간 상호작용","집단원 간의 정보교환과 모방이 상담 성과로 이어질 수 있다"]]}],"20":[{"t":"table","title":"특수집단 진로상담","head":["대상","내용"],"rows":[["여성","진로 및 직업 선택에서 고용상의 차별이 있는지를 알아본다 · 내담자의 성역할 고정관념이 진로발달에 미치는 영향을 확인한다"],["장애인","진로 탐색에서 장애유형에 따른 제한점이 있는지를 고려하여 상담한다 · 내담자의 특성에 따라 찾아가는 상담도 할 수 있다 · 진로 및 직업 상담을 위한 장애유형과 수준에 따른 인프라 구축이 되어야 한다"],["다문화 인식","다문화에 대한 사회인식을 고려한다 · 다문화에 대한 상담자의 지식과 인식은 중요하고 상담에 영향을 미칠 수 있다"],["다문화 상담","내담자의 문화에 대한 일반적인 생각을 이해하는 것이 도움이 된다 · 내담자의 문화적 특성을 고려하여 기존의 상담이론과 기법을 섣불리 적용하지 않도록 유의한다"]]}]};
