(window.TNQ=window.TNQ||[]).push({"terms":{"정서집중형":{"d":"로우가 구분한 부모 양육 유형으로 자녀에게 정서적으로 몰입하는 방식입니다.","r":["회피형","수용형"]},"회피형":{"d":"로우가 구분한 부모 양육 유형으로 자녀에게 거리를 두고 냉담하게 대하는 방식입니다.","r":["정서집중형","수용형"]},"수용형":{"d":"로우가 구분한 부모 양육 유형으로 자녀를 있는 그대로 받아들이는 방식입니다.","r":["정서집중형","회피형"]},"자기개념":{"d":"자신의 능력, 흥미, 가치 등에 대해 스스로 가지는 생각의 전체입니다.","r":["직업정체감"]},"진로적응력":{"d":"변화하는 직업 환경에서 진로 과제와 전환에 대처하는 준비 정도입니다.","r":[]},"직업정체감":{"d":"자신의 직업 목표, 흥미, 능력에 대해 가지는 분명하고 안정된 인식입니다.","r":["자기개념"]},"진로장벽":{"d":"진로 선택과 진행을 가로막는 내적 또는 외적 요인입니다.","r":[]},"도구적 학습":{"d":"행동의 결과로 얻는 보상이나 처벌을 통해 이루어지는 학습입니다.","r":["연합적 학습"]},"연합적 학습":{"d":"두 사건이 함께 나타나는 경험이 반복되며 둘이 연결되어 이루어지는 학습입니다.","r":["도구적 학습"]},"결과기대":{"d":"어떤 행동을 하면 어떤 결과가 따를 것이라고 믿는 예상입니다.","r":["자기효능감"]},"자기효능감":{"d":"어떤 과제를 성공적으로 해낼 수 있다는 자기 능력에 대한 믿음입니다.","r":["결과기대"]},"진로유형면접":{"d":"사비카스가 진로 이야기를 끌어내기 위해 쓰는 구조화된 면접입니다.","r":["생애주제"]},"생애주제":{"d":"진로유형면접 이야기에서 드러나는 삶의 일관된 관심과 의미의 주제입니다.","r":["진로유형면접"]},"기대치 전환":{"d":"새 일자리에 들어갈 때 처음 가졌던 기대와 현실의 차이를 조정하는 일입니다.","r":[]},"라포":{"d":"상담자와 내담자 사이의 신뢰와 친밀감으로 이루어진 관계입니다.","r":[]}},"notes":{"'구성 - 해체 - 재구성 - 협력구성'의 내러티브 방식을 기본으로 한다":"이야기를 만들고 풀어 헤친 뒤 다시 엮고 상담자와 함께 완성하는 서술 방식입니다.","2단계 성유형 획득단계: 초등학교 저학년 시기로 성역할을 지향":"이 시기 아동은 자신의 성별에 어울린다고 여기는 직업을 중심으로 생각합니다.","3단계 사회적 가치를 획득하는 단계: 아동기에서 청소년기에로 이행하는 시기로, 사회적 가치, 능력, 명성을 지향":"사회적 지위와 직업의 명성에 눈뜨고 능력을 따지기 시작하는 단계입니다.","4단계 내적 자아를 확립하는 단계: 청소년기로, 자신만의 흥미, 적성, 가치관, 성격 등을 이해할 수 있다":"청소년기에 자신의 내면 특성을 깨닫고 이를 직업 선택에 연결하게 되는 단계입니다.","가족의 맥락 속에서 내담자 이해를 촉진시켜주는 기법":"가계도처럼 가족 배경을 함께 보면서 내담자가 진로를 어떻게 형성해 왔는지 이해하는 방법입니다.","가치단계: 직업선택을 할 때 관련된 모든 요인들을 인정하고 자신의 가치관 및 생애 목표에 비추어 평가해 본다":"직업 선택의 여러 요인을 받아들이고 자신의 가치관과 삶의 목표에 비추어 판단하는 단계입니다.","개인은 어떤 과제를 성취하기 위하여 과제접근 기술을 사용한다":"과제접근 기술은 문제를 풀려고 목표를 세우고 방법을 짜서 실행하는 개인의 대처 방식입니다.","개인의 직업생활 전환에 영향을 주는 요소로 자아(Self), 지원(Support), 상황(Situation), 전략(Strategies) 등을 강조한다":"전환을 겪는 사람의 자아와 주위 지원과 처한 상황과 대처 전략이 전환의 성패를 좌우한다는 설명입니다.","개인의 진로의사결정 단계를 직업정체감 형성 과정에 따라 예상기와 실천기로 나누어 설명한다":"결정 과정을 직업정체감이 만들어지는 흐름에 맞춰 준비하는 시기와 행동하는 시기로 나눕니다.","개인이 심리적 불균형을 느끼고 어떤 결정을 해야 할 필요성을 인식한다":"인식 단계는 현재 상태와 바라는 상태의 차이를 느끼고 결정이 필요하다는 것을 아는 출발점입니다.","개인이 일에 직면했을 때 분화와 통합을 통하여 직업정체감을 형성한다고 보았다":"일을 접하면서 여러 가능성을 구분하고 하나로 정리하는 과정을 되풀이하며 직업정체감이 생긴다고 본 것입니다.","개인이 환경의 영향을 받기도 하지만, 개인도 환경을 만들어가는 발달의 주체임을 강조한다":"사람은 환경에 영향받는 동시에 환경을 바꾸어 가는 능동적인 존재라고 봅니다.","경제적 안정, 정서적 안정, 건강, 전환 기술, 지지적 직업환경, 전환에 대한 지지 등":"전환을 잘 넘기도록 돕는 조건들로, 생활의 안정과 건강과 주변의 지지를 포함합니다.","고도의 기억력을 필요로 하는 과제":"인지적 정보처리이론은 진로문제를 풀 때 많은 정보를 한꺼번에 기억하고 다뤄야 한다고 봅니다.","공통적으로 필요로 하는 직업정보를 효율적으로 제공할 수 있는 기회가 된다":"같은 정보가 필요한 사람들에게 한 번에 전달할 수 있어 시간과 노력이 절약됩니다.","구체화 단계: 가능한 대안을 선택하며, 각 대안의 장단점을 검토하여 서열화 및 조직화 한다":"대안을 좁히면서 장단점을 비교해 우선순위를 매기는 단계입니다.","근접맥락과 배경맥락으로 세분화된다":"환경맥락적 요인은 당장 영향을 주는 근접 요인과 오래전부터 깔린 배경 요인으로 나뉩니다.","기존의 이론들은 개인의 진로에 영향을 주는 객관적 맥락과 주관적 맥락의 영향을 모두 포함하지 못하고 있다":"기존 이론은 외부 환경과 개인의 주관적 경험이라는 두 측면을 함께 다루지 못했다는 비판입니다.","기존의 이론들은 매칭 또는 조화의 역동에만 초점을 두고 인간의 적응적인 특성을 충분히 반영하지 못하고 있다":"사람과 직업을 맞추는 데만 집중해 사람이 변화에 적응해 가는 면을 놓쳤다는 비판입니다.","기존의 이론들은 인간이 현상과 경험을 새롭게 해석하고 의미부여하고 있는 점을 간과하고 있다":"사람이 겪은 일을 스스로 해석하고 의미를 만든다는 점을 이론이 빠뜨렸다는 지적입니다.","내담자가 가장 중시하는 욕구가 무엇인가를 통해서 내담자의 생활양식을 확인한다":"가장 우선하는 욕구를 물으면 내담자가 삶을 살아가는 기본 방식이 드러납니다.","내담자가 기대하는 것이 무엇인가와 같은 질문을 통해 촉진적 관계를 형성한다":"상담에서 무엇을 원하는지 묻는 것이 내담자가 마음을 열고 참여하게 만드는 관계의 출발이 됩니다.","내담자가 선택 가능한 진로를 일찍 제외하도록 만든 진로장벽을 확인하고 평가하는 것이 중요하다":"내담자가 가능성을 일찍 접게 만든 장애물이 무엇인지 찾아 그 영향의 크기를 가늠해야 합니다.","내담자 가족의 지배적인 직업가치를 확인하기 위해 사용할 수 있다":"가족이 대대로 중요하게 여기는 직업 가치가 무엇인지 밝히는 데 쓸 수 있습니다.","내담자가 진로설계를 스스로 할 수 있도록 돕는다":"상담자가 대신 정해 주지 않고 내담자가 자기 진로 계획을 직접 세울 수 있게 합니다.","내담자가 호소하는 문제도 중요하지만 예기치 않은 사건이나 문제발생을 대비하는 역량을 키워주는 것이 중요하다":"지금의 고민을 푸는 데 더해 앞으로 닥칠 뜻밖의 일에 대처할 힘을 길러 주는 것이 상담의 방향입니다.","내담자로 하여금 진로나 직업선택과 관련된 본인의 이야기(storytelling)를 하도록 한다":"사비카스 상담은 내담자가 자기 진로에 대한 이야기를 직접 들려주게 하면서 시작합니다.","내담자마다 성격, 적성, 흥미 등이 다름을 고려한다":"사람마다 특성이 달라 같은 진로 조언이 모든 내담자에게 맞지는 않습니다.","내담자에게 특정한 일을 좋아하는 이유 등을 질문하면서 내담자의 문제를 구체화 한다":"어떤 일을 왜 좋아하는지 물으면 막연한 고민이 구체적 문제로 정리됩니다.","내담자의 대인관계기술을 향상시킨다":"직업 생활에서 사람들과 잘 지내는 기술이 부족하면 진로 적응이 어려워 이를 길러 줍니다.","내담자의 독특성 또는 개별성을 탐색하기 위하여 사례연구나 검사결과를 통해 자료를 수집하고 요약한다":"특성요인 상담은 내담자의 고유한 특성을 사례와 검사 자료로 모아 정리하는 단계에서 시작합니다.","내담자의 문제를 내담자의 입장에서 이해한다":"상담자 기준이 아니라 내담자가 느끼는 방식 그대로 문제를 이해해야 합니다.","내담자의 문화에 대한 일반적인 생각을 이해하는 것이 도움이 된다":"내담자가 속한 문화에서 통용되는 가치와 통념을 알면 그의 선택을 이해하기 쉽습니다.","내담자의 문화적 특성을 고려하여 기존의 상담이론과 기법을 섣불리 적용하지 않도록 유의한다":"기존 이론은 다른 문화권에 맞지 않을 수 있어 문화 차이를 먼저 감안한 뒤 적용해야 합니다.","내담자의 비합리적인 진로기대 및 진로신념 등을 살펴보면서 내담자의 관점을 수용한다":"비현실적인 기대와 신념을 비난하지 않고 내담자가 세상을 보는 시각으로 받아들입니다.","내담자의 성역할 고정관념이 진로발달에 미치는 영향을 확인한다":"남자 일과 여자 일이 정해져 있다는 생각이 진로 선택의 폭을 좁혔는지 확인합니다.","내담자의 의사결정기술을 향상시킨다":"진로를 스스로 정하는 데 필요한 의사결정 방법을 익히게 하는 것이 목표의 하나입니다.","내담자의 잘못된 직업정보를 점검하고 수정하는 것이 중요하다":"그릇된 직업 정보는 진로 판단을 왜곡하므로 확인하여 바로잡아 주어야 합니다.","내담자의 잠재력을 발견하고 발현될 수 있도록 돕는다":"내담자 자신도 모르는 가능성을 찾아내 실제로 발휘하도록 이끄는 일입니다.","내담자의 정보를 수집하는 단계에서 사용될 수 있다":"상담 초기에 내담자의 배경과 관심사를 모으는 도구로 쓸 수 있습니다.","내담자의 진로기대형성에 중요한 역할을 한 가족이 누구인지 확인이 가능하다":"진로에 대한 기대를 만드는 데 가장 큰 영향을 준 가족 구성원을 찾아낼 수 있습니다.","내담자의 진로에 미친 영향을 확인할 수 있다":"가족이 내담자의 진로 생각에 어떤 영향을 주었는지 드러낼 수 있습니다.","내담자의 진로장벽을 확인할 수 있다":"가족과 관련된 제약이 진로에 걸림돌이 되고 있는지 확인할 수 있습니다.","내담자의 진로정보를 여러 가지 방법으로 탐색할 수 있다":"가족 맥락을 보는 방법으로 내담자가 이미 가진 직업 정보와 경험을 폭넓게 끌어낼 수 있습니다.","내담자의 진로탐색활동을 구체적으로 돕는다":"직업과 진로 정보를 직접 찾아보는 활동이 실제로 이루어지도록 상담자가 지원합니다.","내담자의 특성에 따라 찾아가는 상담도 할 수 있다":"이동이 어려운 내담자에게는 상담자가 직접 방문하는 방식도 쓸 수 있습니다.","내담자의 호기심(curiosity), 인내심(persistence), 유연성(flexibility), 낙관성(optimism), 위험감수(risk-taking) 등의 기술을 촉진시킨다":"우연을 기회로 바꾸는 데 필요한 다섯 가지 태도를 내담자가 갖추도록 이끕니다.","능력단계: 직업에 따라 보수와 필요로 하는 교육이 다르다는 것을 알게 된다":"자신의 능력을 인식하면서 직업마다 보수와 요구되는 교육이 다르다는 점도 이해하기 시작합니다.","다문화에 대한 사회인식을 고려한다":"다문화 내담자는 사회의 편견이나 인식에 영향을 받으므로 그 환경을 상담에 반영합니다.","다문화에 대한 상담자의 지식과 인식은 중요하고 상담에 영향을 미칠 수 있다":"상담자가 다문화에 대해 얼마나 알고 어떤 태도를 가졌는지에 따라 상담의 질이 달라집니다.","매슬로우(A. Maslow) 이론의 영향을 받았다":"로우는 욕구가 위계를 이룬다는 매슬로우의 생각을 이어받아 직업 선택을 욕구로 설명했습니다.","부가직업정보로 직업별 필요한 정규교육수준, 숙련기간, 자격면허 등을 제공":"직업사전에는 직업마다 요구되는 학력과 익히는 데 걸리는 기간, 자격 같은 정보가 실립니다.","부모와 자녀 간의 상호작용은 정서집중형, 회피형, 수용형으로 구분하였다":"부모가 자녀를 대하는 방식을 세 갈래로 나누어 각각이 직업 지향에 다른 영향을 준다고 했습니다.","부적절한 자기효능감이나 결과에 대한 기대 때문에 내담자가 제외한 진로대안들을 다시 확인하는 것이 중요하다":"잘못된 자신감이나 결과 예상 탓에 버린 진로 중에 다시 고려할 만한 것이 있는지 찾아봅니다.","사람들은 자아개념에 부합하는 직업들을 포기할 때 흥미, 명성, 성유형의 순서대로 포기한다":"타협할 때는 흥미를 가장 먼저 내려놓고 성유형에 맞는 직업은 가장 늦게까지 지키려 합니다.","사용목적을 내담자에게 설명해야 한다":"내담자가 왜 가족에 대한 질문을 받는지 알아야 거부감 없이 응답할 수 있습니다.","상담의 성공여부는 내담자가 상담실 밖에서 다양한 경험을 위해 얼마나 노력하고 성장하는가에 좌우된다":"상담 효과는 내담자가 상담실 밖에서 새로운 경험을 얼마나 시도하는지로 판단합니다.","상담자와 내담자의 긍정적인 라포 형성에 도움을 준다":"관심을 갖고 묻고 들어 주는 과정이 두 사람 사이의 신뢰를 쌓아 줍니다.","새로운 일자리로 진입하는 경우 기대치 전환이 중요하다고 보고 있다":"새 일터에서는 미리 가졌던 기대를 현실에 맞게 고치는 과정이 적응의 열쇠가 됩니다.","새로운 일자리에 적응하기 위해서는 네트워킹, 가족지원정책, 경제적 안정 등 다양한 차원의 개입이 요구된다":"새 직장 적응에는 개인의 노력만이 아니라 인맥과 제도와 경제 여건 같은 여러 층위의 지원이 필요합니다.","선택기는 구체화 과정을 통해 나타난 결과를 토대로 명확한 목표를 설정하는 단계":"비교한 결과를 바탕으로 하나를 골라 분명한 목표를 정하는 시기입니다.","성격과 직업분류를 통합하였다":"사람의 성격과 직업의 구분을 한 이론에서 연결해 직업 선택을 설명한 것이 특징입니다.","성격유형과 환경모형 간의 관련 정도":"홀랜드에서 일관성은 개인이 가진 유형들 사이나 유형과 환경 사이가 얼마나 가까운지를 말합니다.","성인기의 진로발달을 이해하기 위해서는 진로적응력의 개념이 중요하다고 보았다":"어른이 되어서도 직업 환경이 바뀌므로 변화에 대처하는 진로적응력이 필요하다고 설명했습니다.","슬로스버그(N. Schlossberg)가 나눈 유형":"슬로스버그가 인생의 전환을 일어나는 방식에 따라 구분한 유형 가운데 예측된 전환에 대한 설명입니다.","아동기부터 일의 세계에 관한 여러 경험을 하게 되면서 일과 관련된 자기개념을 형성한다고 하였다":"어린 시절부터 일에 대해 보고 겪은 것들이 쌓여 나는 어떤 일에 맞는 사람인가 하는 자기개념이 만들어집니다.","아동기의 경험 중 부모-자녀 관계는 직업선택에 중요한 영향을 미치는 요인으로 간주하였다":"어린 시절 부모와 맺은 관계가 나중의 직업 선택 방향을 정하는 데 크게 작용한다고 본 것입니다.","아들러(A. Adler)의 개인심리학에 기초하였다":"진로유형면접은 개인의 생활양식을 중시하는 아들러의 이론을 바탕으로 만들어졌습니다.","유형간의 상대적 중요도의 관계":"변별성은 한 유형이 다른 유형들에 비해 얼마나 뚜렷하게 두드러지는지를 나타냅니다.","육각형 내에서 유형들 간의 거리는 그들의 이론적 관계에 반비례한다":"육각형에서 가까이 놓인 유형일수록 이론상 서로 더 비슷하다는 뜻입니다.","의사결정에 대한 개인적인 책임을 부정하고 그 책임을 외부로 돌리는 경향이 있다":"의존적 유형은 결정의 책임이 자기에게 있다는 것을 받아들이지 않고 남이나 환경 탓으로 돌립니다.","의사결정의 기초로 상상을 사용하고, 현재의 감정에 주의를 기울이며, 정서적 감각을 사용한다":"직관적 유형은 상상과 지금의 느낌을 근거로 결정하는 방식입니다.","일과 관련한 교육적, 직업적, 심리사회적 정보":"진로정보는 직업 자체뿐 아니라 교육과 심리사회적 측면까지 포함하는 넓은 정보입니다.","일반적성검사와 특수적성검사가 있다":"적성분류검사는 폭넓은 능력을 재는 종류와 특정 분야의 능력을 재는 종류로 나뉩니다.","자기효능감 점검, 결과기대에 대한 탐색과 현실성 강화, 진로준비행동 촉진 등이 중요한 개입 전략이다":"스스로 해낼 수 있다는 믿음과 결과 예상이 현실에 맞는지 살피고 준비 행동을 늘리는 개입입니다.","자신의 직업적 적합성을 객관적이고 현실적으로 이해할 수 있다":"다른 집단원과 견주며 자기 특성이 직업에 맞는지 현실적으로 가늠할 수 있습니다.","자신의 진로계획을 검토하게 하는 기회를 제공한다":"다른 사람의 계획을 접하면서 자기 계획의 빈틈을 점검하는 계기가 됩니다.","자원봉사, 직업체험, 인턴십 활동 등과 같이 직접적인 경험에 의해 수집한 자료도 포함":"책이나 자료에서 얻은 정보만이 아니라 몸으로 겪어 얻은 정보도 진로정보에 들어갑니다.","적응적 진로행동에 대하여 예상되는 결과에 관한 기대와 개인적 신념으로 가치와 관련된다":"결과기대는 진로 행동을 하면 어떤 결과가 올지에 대한 믿음이며 그 결과를 얼마나 가치 있게 여기는지와 이어집니다.","전환단계: 주관적인 요소에서 현실적인 외적 요소로 관심을 돌리기 시작한다":"자기 마음에서 시작한 선택 기준이 일자리 사정 같은 현실 조건으로 옮겨 가는 단계입니다.","정확한 정보를 수집하고, 논리적으로 의사결정을 해 나가며, 의사결정에 대한 책임을 진다":"하렌의 합리적 유형은 자료와 논리에 따라 결정하고 결과도 스스로 책임집니다.","조정가능성 및 문제의 가능한 결과를 판단하고, 이를 통해 내담자가 고려해야 할 대안적 조치들과 조정사항들을 찾는다":"문제가 바뀔 수 있는지와 예상 결과를 따져 내담자가 택할 수 있는 대안과 조정할 부분을 찾습니다.","좋아함-무관심-싫어함 정도를 파악하여 직업군에 대한 흥미 형태를 결정한다":"세 가지 반응을 비교해 어떤 직업군과 흥미 모양이 닮았는지 정합니다.","준비도, 자기효능감(confidence), 지각된 지지, 내외적 통제, 자기중심-관계중심(independence-interdependence)으로 구성":"진로전환검사가 재는 다섯 가지 요소로, 전환에 대한 마음가짐과 자원을 나타냅니다.","중학생에게는 진로탐색을 위한 활동을 하도록 한다":"중학생은 자신의 흥미와 적성을 직업과 연결해 보는 진로탐색 활동이 알맞습니다.","지식 구조의 계속적인 성장과 변화를 내포한다":"진로발달은 직업과 자신에 대한 지식이 쌓이고 재편되는 과정이라는 설명입니다.","직능수준을 교육과 훈련정도에 따라 4단계로 구분":"직능수준은 직무를 수행하는 데 필요한 교육과 훈련 정도에 따라 네 단계로 매겨집니다.","직업과 관련된 가치체계를 측정하기 위한 검사":"일에서 무엇을 가장 소중히 여기는지를 재는 가치 검사입니다.","직업생활 전환에는 청사진과 위협의 양가적인 특성이 있다":"직업 전환은 새 기회가 되는 동시에 불안을 주는 두 가지 면을 함께 지닙니다.","직업에 대한 이해를 향상시킴으로써 합리적인 의사결정과정을 돕는다":"직업을 정확히 알아야 근거를 갖고 선택할 수 있으므로 진로정보가 결정을 뒷받침합니다.","직업을 대분류, 중분류, 소분류, 세분류로 구분":"한국고용직업분류는 직업을 네 층의 단계로 점차 세밀하게 나누어 정리합니다.","직업을 흥미에 기초하여 8개 직업군으로 제안하였다":"로우는 사람이 흥미를 갖는 대상을 기준으로 직업을 여덟 군으로 나누었습니다.","직업정보뿐만 아니라 내담자 이해와 관련한 다양한 정보를 포함":"직업에 대한 지식에 더해 내담자 자신의 특성과 상황을 알려 주는 정보까지 아우릅니다.","진로개발과정에서 우연(happenstance)이 중요한 영향을 준다":"계획하지 않은 만남과 사건이 진로를 바꾸는 계기가 되는 일이 흔하다는 주장입니다.","진로결정과정에서 개인이 통제하기 어려운 요인들이 영향을 미치고 있음을 강조한다":"진로 선택에는 본인이 조절할 수 없는 환경과 사건의 영향이 크다는 점을 부각합니다.","진로계획 태도와 능력을 측정한다":"진로를 계획하는 데 필요한 마음가짐과 실제 능력을 함께 측정합니다.","진로 관련 검사를 실시하고 해석한다":"흥미와 적성 등 진로 검사를 실시한 뒤 그 결과가 내담자에게 뜻하는 바를 풀어 줍니다.","진로문제를 해결하는 개인의 능력과 관련된다":"진로성숙도는 진로 문제를 푸는 개인의 능력이 얼마나 갖춰졌는가와 이어집니다.","진로 및 직업 상담을 위한 장애유형과 수준에 따른 인프라 구축이 되어야 한다":"장애 종류와 정도에 맞는 시설과 지원 체계가 갖춰져야 진로 상담을 받을 수 있습니다.","진로 및 직업 선택에서 고용상의 차별이 있는지를 알아본다":"성별을 이유로 한 채용이나 승진의 불이익이 내담자의 진로에 영향을 주는지 확인합니다.","진로발달에 있어서 역할과 시간의 개념을 도입하였다":"한 사람이 맡는 여러 삶의 역할과 시기별 변화를 함께 보는 생애진로무지개 관점입니다.","진로발달을 전 생애적인 발달과정으로 보았다":"수퍼는 진로 선택을 한 시점의 일이 아니라 평생에 걸쳐 변화하는 과정으로 이해했습니다.","진로발달이 예상하지 못했던 사건과 경험, 즉 우연에 의해 변화될 수 있음을 충분히 고려하지 못하고 있다":"뜻밖의 사건이 진로를 바꿀 수 있다는 사실을 기존 이론이 충분히 반영하지 않았다는 비판입니다.","진로사정, 일상적인 하루, 강점과 장애, 요약 등의 · 네 부분으로 구성되어 있다":"면접은 진로 이력, 평소 하루, 강점과 어려움, 정리의 네 영역으로 나뉩니다.","진로유형면접 자료를 근거로 내담자의 생애주제(life themes)를 이끌어 낸다":"면접에서 나온 이야기들에 반복되는 관심사를 추려 그 사람의 삶의 주제로 정리합니다.","진로이야기를 끌어내기 위해 진로유형면접(career style interview)을 사용한다":"정해진 질문들로 구성된 면접으로 내담자가 자신의 진로 이야기를 꺼내도록 합니다.","진로적응도의 자원과 전략에 따라서 관심, 통제, 호기심, 자신감의 차원으로 제시하였다":"사비카스는 진로적응을 관심과 통제와 호기심과 자신감 네 영역의 자원으로 설명했습니다.","진로전환에는 양가적인 특성이 있다":"진로 전환은 기대와 두려움처럼 상반된 감정이 함께 생기는 사건입니다.","진로정보 수집단계에서 사용될 수 있는 질적 평가과정":"점수 대신 면담과 이야기로 진로 정보를 모으는 평가 방식입니다.","진로 탐색에서 장애유형에 따른 제한점이 있는지를 고려하여 상담한다":"장애 종류에 따라 접근하기 어려운 직업이 있을 수 있어 이를 감안해 탐색합니다.","집단원 간의 정보교환과 모방이 상담 성과로 이어질 수 있다":"집단원끼리 정보를 나누고 서로의 행동을 따라 하면서 변화가 생길 수 있습니다.","집단의 형태로 진로상담이 진행됨을 의미한다":"집단진로상담은 여러 내담자가 함께 모여 진로 문제를 다루는 방식입니다.","초등학교 6학년부터 고등학교 3학년을 대상으로 진로의사결정에 대한 태도와 능력을 측정하기 위해 개발":"진로성숙도검사는 학령기 후반 학생의 진로 결정 태도와 능력을 재려고 만들어졌습니다.","초등학생에게는 진로인식을 위한 활동을 하도록 한다":"초등학생은 여러 직업이 있다는 것을 알아 가는 진로인식 단계에 맞는 활동을 합니다.","탐색 단계: 자신이 정한 목적을 전반적으로 고려하고, 대안을 추진해 나갈 수 있는 능력과 여건을 평가하며, 대안에 대한 가치를 분석한다":"예상기의 첫 단계에서는 목적과 대안을 살피고 실행할 능력과 여건이 되는지를 따집니다.","특정 직업에 종사하고 있는 사람들이 비슷한 흥미를 갖고 있다는 전제로 개발":"스트롱검사는 직업인들의 흥미 패턴이 서로 닮았다는 가정 위에서 만들어졌습니다.","특정한 결과에 도움이 되는 행동에 전념하려는 의도나 계획이며, 행동을 자기조절하는데 있어서 중요하다":"목표는 원하는 결과를 얻기 위해 어떤 행동을 하겠다는 결심이며 스스로 행동을 조절하게 합니다.","학습경험은 도구적 학습과 연합적 학습을 통하여 이루어진다":"크럼볼츠는 보상과 처벌로 배우는 학습과 사건의 연결로 배우는 학습이 진로 신념을 만든다고 보았습니다.","합리적, 직관적, 의존적 유형을 측정한다":"하렌이 구분한 세 가지 의사결정 유형 가운데 어느 쪽에 가까운지 알아냅니다.","합리적인 의사결정능력을 향상시킨다":"정보를 모으고 비교해 근거 있게 결정하는 능력을 길러 주는 일입니다.","환경과의 상호작용을 통해 무엇을 학습했는가를 중요시한다":"타고난 성향보다 환경과 주고받으며 어떤 것을 배웠는지가 진로 선택을 설명한다고 봅니다.","환경적 정체성은 환경이나 조직이 분명하고 통합된 목표, 일, 보상이 일관되게 주어질 때 생긴다":"조직의 목표와 일과 보상이 한결같고 분명할수록 환경의 정체성이 뚜렷해집니다.","흥미는 다시 진로대안 선택의 목표에 영향을 준다":"사회인지진로이론에서 흥미는 어떤 진로를 목표로 삼을지에도 다시 영향을 미칩니다.","흥미단계: 자신의 흥미에 입각해서 직업을 선택하려는 경향":"긴즈버그의 첫 단계로, 아동이 좋아하는 것을 기준으로 직업을 생각합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
